class ContaBancaria:
    def __init__(self, titular, saldo=0.0):
        self.titular = titular
        self.saldo = saldo

    def depositar(self, valor):
        self.saldo += valor
        return self.saldo

conta = ContaBancaria("Ana", 100.0)
conta.depositar(50.0)
print(f"Saldo atual: R$ {conta.saldo:.2f}") # 150.00

class Cachorro:
    def __init__(self, nome):
        self.nome = nome
    def latir(self):
        return f"{self.nome} diz: Au Au!"

pet = Cachorro("Rex")
print(pet.latir())

class Animal:
    def __init__(self, nome):
        self.nome = nome

class Gato(Animal):
    def miar(self):
        return f"{self.nome} faz Miau!"

bichano = Gato("Mingau")
print(bichano.miar())
